#!/usr/bin/env python3
"""Writes xbox/docs/sdk-symbols.md from build/link_stubs.c (generated by link_resolve.py on every Xbox build):
the symbols the game links against that nothing implements yet, grouped by subsystem.

    python3 xbox/tools/gen_sdk_symbols.py
"""
import collections
import datetime
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
STUBS = os.path.join(ROOT, 'build', 'link_stubs.c')
OUT = os.path.join(ROOT, 'docs', 'sdk-symbols.md')

PREFIXES = [
    ('GX', 'GX (graphics)'), ('AXFX', 'AXFX (audio effects)'), ('AXART', 'AX (audio)'), ('AX', 'AX (audio)'),
    ('MIX', 'AX (audio)'), ('SYN', 'AX (audio)'), ('SEQ', 'AX (audio)'), ('AI', 'AX (audio)'),
    ('ARQ', 'ARAM'), ('AR', 'ARAM'), ('DVD', 'DVD'), ('CARD', 'CARD (memory card)'), ('PAD', 'PAD'), ('SI', 'PAD'),
    ('VI', 'VI (video)'), ('OS', 'OS'), ('PPC', 'OS'), ('DB', 'OS'), ('LC', 'OS'),
    ('ADX', 'CRI movies'), ('mwPly', 'CRI movies'), ('PC', 'SN host file server (debug)'),
]


def short(sym):
    return sym[1:] if sym.startswith('_') and not sym.startswith('__') else sym


def group(sym):
    n = short(sym).lstrip('?')
    for p, g in PREFIXES:
        if n.startswith(p):
            return g
    return 'game-side (declaration/definition mismatch, dead code)'


def main():
    items = [l[3:].strip().split() for l in open(STUBS) if l.startswith(' *   ')]
    groups = collections.defaultdict(list)
    for kind, sym in items:
        groups[group(sym)].append(short(sym))
    n_fn = sum(1 for k, _ in items if k == 'fn')
    out = ['# SDK symbols the game links against that the port does not implement yet', '',
           'Generated by `tools/gen_sdk_symbols.py` from `build/link_stubs.c` (written by `tools/link_resolve.py` on every',
           'Xbox build). Each entry is bound to a logging catch-all; implementing it in `xbox/port/` removes it from',
           'the list on the next build.', '',
           f'Total: {len(items)} ({n_fn} functions, {len(items) - n_fn} data). Snapshot {datetime.date.today()}.', '']
    for g, syms in sorted(groups.items(), key=lambda kv: -len(kv[1])):
        out += [f'## {g} ({len(syms)})', '', '`' + '`, `'.join(sorted(syms)) + '`', '']
    with open(OUT, 'w', newline='\n') as f:
        f.write('\n'.join(out))
    for g, syms in sorted(groups.items(), key=lambda kv: -len(kv[1])):
        print(f'{len(syms):4d} {g}')


if __name__ == '__main__':
    main()
